create table if not exists public.business_restroom_service_updates (
  id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, restroom_facility_id uuid, event_kind text not null check (event_kind in ('cleaned','restocked','inspected','repaired','deep_cleaned','renovated','closed','reopened')), note text, proof_url text, actor_user_id uuid not null references public.profiles(id) on delete restrict default auth.uid(), reported_at timestamptz not null default now(), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists business_restroom_service_updates_location_time_idx on public.business_restroom_service_updates(location_id,reported_at desc); create index if not exists business_restroom_service_updates_business_time_idx on public.business_restroom_service_updates(business_id,reported_at desc); alter table public.business_restroom_service_updates enable row level security; revoke all on public.business_restroom_service_updates from anon,authenticated;
create table if not exists public.kleenest_evidence_events (id uuid primary key default gen_random_uuid(),location_id uuid not null references public.locations(id) on delete cascade,business_id uuid references public.businesses(id) on delete set null,actor_user_id uuid references public.profiles(id) on delete set null,source_type text not null,source_id uuid,evidence_kind text not null,provenance text not null check (provenance in ('community','business_reported','fleet','partner','system','owner')),observed_at timestamptz not null default now(),confidence numeric not null default .5 check (confidence between 0 and 1),payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists kleenest_evidence_events_location_time_idx on public.kleenest_evidence_events(location_id,observed_at desc); create index if not exists kleenest_evidence_events_business_time_idx on public.kleenest_evidence_events(business_id,observed_at desc); create unique index if not exists kleenest_evidence_events_source_dedupe_idx on public.kleenest_evidence_events(source_type,source_id,evidence_kind) where source_id is not null; alter table public.kleenest_evidence_events enable row level security; revoke all on public.kleenest_evidence_events from anon,authenticated;
create table if not exists public.kleenest_intelligence_policy(policy_key text primary key,config jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),updated_by uuid references public.profiles(id) on delete set null); alter table public.kleenest_intelligence_policy enable row level security; revoke all on public.kleenest_intelligence_policy from anon,authenticated;
insert into public.kleenest_intelligence_policy(policy_key,config) values('global_v1',jsonb_build_object('service_freshness_hours',jsonb_build_object('cleaned',72,'restocked',48,'inspected',24,'repaired',120,'deep_cleaned',168,'renovated',720,'closed',1,'reopened',24),'service_base_score',jsonb_build_object('cleaned',100,'restocked',90,'inspected',80,'repaired',95,'deep_cleaned',100,'renovated',100,'closed',0,'reopened',80),'service_min_interval_minutes',15,'fleet',jsonb_build_object('trusted_freshness_min',45,'trusted_confidence_min',40,'restroom_desert_minutes',45),'launch',jsonb_build_object('freshness_min',50,'confidence_min',40,'fresh_location_pct_target',65,'claimed_location_pct_target',20),'fix_first',jsonb_build_object('freshness_weight',0.45,'cleanliness_weight',0.25,'active_case_weight',20,'negative_observation_weight',5))) on conflict(policy_key) do nothing;
create table if not exists public.consumer_bathroom_fit_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,preferences jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now()); alter table public.consumer_bathroom_fit_preferences enable row level security; revoke all on public.consumer_bathroom_fit_preferences from anon,authenticated;
create or replace function public.kleenest_service_freshness_score(p_event_kind text,p_reported_at timestamptz) returns numeric language plpgsql stable security definer set search_path to '' as $$ declare v_config jsonb;v_hours numeric;v_base numeric;v_age_hours numeric; begin select config into v_config from public.kleenest_intelligence_policy where policy_key='global_v1'; v_hours:=greatest(1,coalesce((v_config->'service_freshness_hours'->>lower(coalesce(p_event_kind,'')))::numeric,72)); v_base:=greatest(0,least(100,coalesce((v_config->'service_base_score'->>lower(coalesce(p_event_kind,'')))::numeric,70))); if lower(coalesce(p_event_kind,''))='closed' then return 0; end if; v_age_hours:=greatest(0,extract(epoch from(now()-coalesce(p_reported_at,now()-interval '365 days')))/3600); return round(greatest(0,least(100,v_base*(1-(v_age_hours/v_hours))))::numeric,1); end $$;
create or replace function public._converge_data_feature_to_kleenest_evidence() returns trigger language plpgsql security definer set search_path to '' as $$ declare v_provenance text; begin if new.location_id is null or coalesce(new.event_validity,'valid')<>'valid' then return new; end if; v_provenance:=coalesce(new.metadata->>'provenance',case when new.actor_user_id is not null then 'community' else 'system' end); if v_provenance not in ('community','business_reported','fleet','partner','system','owner') then v_provenance:='system'; end if; insert into public.kleenest_evidence_events(location_id,business_id,actor_user_id,source_type,source_id,evidence_kind,provenance,observed_at,confidence,payload) values(new.location_id,new.business_id,new.actor_user_id,coalesce(nullif(new.source_table,''),'data_feature_events'),coalesce(new.source_id,new.id),new.event_type,v_provenance,new.occurred_at,coalesce(new.confidence,.5),coalesce(new.metadata,'{}'::jsonb)) on conflict do nothing; return new; end $$;
drop trigger if exists trg_data_feature_to_kleenest_evidence on public.data_feature_events; create trigger trg_data_feature_to_kleenest_evidence after insert on public.data_feature_events for each row execute function public._converge_data_feature_to_kleenest_evidence();
insert into public.kleenest_evidence_events(location_id,business_id,actor_user_id,source_type,source_id,evidence_kind,provenance,observed_at,confidence,payload) select e.location_id,e.business_id,e.actor_user_id,coalesce(nullif(e.source_table,''),'data_feature_events'),coalesce(e.source_id,e.id),e.event_type,case when coalesce(e.metadata->>'provenance','') in ('community','business_reported','fleet','partner','system','owner') then e.metadata->>'provenance' when e.actor_user_id is not null then 'community' else 'system' end,e.occurred_at,coalesce(e.confidence,.5),coalesce(e.metadata,'{}'::jsonb) from public.data_feature_events e where e.location_id is not null and e.event_validity='valid' and e.occurred_at>=now()-interval '90 days' on conflict do nothing;
create or replace function public.compute_bathroom_intelligence(p_location_id uuid) returns public.location_bathroom_intelligence language plpgsql security definer set search_path to '' as $$ declare v_category text;v_positive int:=0;v_negative int:=0;v_customers int:=0;v_permissive int:=0;v_public int:=0;v_community_pos int:=0;v_community_neg int:=0;v_evidence int:=0;v_pos boolean:=false;v_neg boolean:=false;v_access text:='unknown';v_status text:='unknown';v_prior numeric:=0;v_source numeric:=0;v_conf numeric:=0;v_age_days numeric:=9999;v_community_fresh numeric:=0;v_service_fresh numeric:=0;v_fresh numeric:=0;v_service_kind text;v_service_at timestamptz;v_row public.location_bathroom_intelligence; begin select lower(coalesce(place_type,'')) into v_category from public.locations where id=p_location_id; select coalesce(toilets_positive,0),coalesce(toilets_negative,0),coalesce(toilets_access_customers,0),coalesce(toilets_access_permissive,0),coalesce(toilets_access_public,0) into v_positive,v_negative,v_customers,v_permissive,v_public from public.external_observation_live_summary where location_id=p_location_id; select count(*) filter(where observation_type in('clean','supplies_ok','open','accessible','changing_table','bathroom_present')),count(*) filter(where observation_type in('dirty','supplies_low','closed','not_accessible','no_changing_table','bathroom_missing')),coalesce(extract(epoch from(now()-max(created_at)))/86400,9999) into v_community_pos,v_community_neg,v_age_days from public.restroom_observations where location_id=p_location_id; select event_kind,reported_at into v_service_kind,v_service_at from public.business_restroom_service_updates where location_id=p_location_id order by reported_at desc limit 1; v_evidence:=coalesce(v_positive,0)+coalesce(v_negative,0)+coalesce(v_customers,0)+coalesce(v_permissive,0)+coalesce(v_public,0)+v_community_pos+v_community_neg; v_pos:=v_evidence>0 and coalesce(v_positive,0)+coalesce(v_customers,0)+coalesce(v_permissive,0)+coalesce(v_public,0)+v_community_pos>0; v_neg:=coalesce(v_negative,0)+v_community_neg>0; v_prior:=case when v_category in('restaurant','gas_station','cafe','shopping','service','health','library','restroom','hotel','bar','fast_food') then 75 when v_category in('park','dog_park','public_safety','transit','travel') then 50 else 25 end; v_source:=least(100,v_evidence*12.5); v_community_fresh:=greatest(0,least(100,100-(v_age_days*3.333333))); if v_service_at is not null then v_service_fresh:=public.kleenest_service_freshness_score(v_service_kind,v_service_at);end if; v_fresh:=greatest(v_community_fresh,v_service_fresh); if v_pos and v_neg then v_status:='uncertain';elsif v_pos then v_status:='confirmed';elsif v_neg then v_status:='no_bathroom';elsif v_prior>=75 then v_status:='likely';elsif v_prior>=50 then v_status:='uncertain';end if; if coalesce(v_customers,0)>0 then v_access:='customers';elsif coalesce(v_public,0)>0 then v_access:='public';elsif coalesce(v_permissive,0)>0 then v_access:='permissive';elsif v_neg and not v_pos then v_access:='none';end if; v_conf:=case when v_pos and v_neg then 60 when v_pos then least(99,80+v_source*.19) when v_neg then 95 when v_prior>=75 then v_prior else greatest(20,v_prior) end; v_conf:=greatest(0,least(99,v_conf*(0.5+0.5*v_community_fresh/100))); insert into public.location_bathroom_intelligence as bi(location_id,status,access,confidence,evidence_count,explicit_positive,explicit_negative,category_prior,source_score,freshness_score,computed_at,updated_at) values(p_location_id,v_status,v_access,v_conf,v_evidence,v_pos,v_neg,v_prior,v_source,v_fresh,now(),now()) on conflict(location_id) do update set status=excluded.status,access=excluded.access,confidence=excluded.confidence,evidence_count=excluded.evidence_count,explicit_positive=excluded.explicit_positive,explicit_negative=excluded.explicit_negative,category_prior=excluded.category_prior,source_score=excluded.source_score,freshness_score=excluded.freshness_score,computed_at=excluded.computed_at,updated_at=now() returning * into v_row; return v_row; end $$;
create or replace function public.location_kleenest_now(p_location_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_l public.locations;v_bi public.location_bathroom_intelligence;v_lc public.location_confidence;v_service public.business_restroom_service_updates;v_service_score numeric:=0;v_community_age numeric:=9999;v_community_score numeric:=0;v_fresh numeric:=0;v_source text:='inferred';v_confirmations int:=0;v_conflicts int:=0;v_label text;v_availability text:='unknown'; begin select * into v_l from public.locations where id=p_location_id;if not found then raise exception 'Location not found';end if; select * into v_bi from public.location_bathroom_intelligence where location_id=p_location_id; select * into v_lc from public.location_confidence where location_id=p_location_id; select * into v_service from public.business_restroom_service_updates where location_id=p_location_id order by reported_at desc limit 1; select coalesce(extract(epoch from(now()-max(created_at)))/86400,9999),count(distinct user_id) filter(where user_id is not null),count(*) filter(where observation_type in('dirty','supplies_low','closed','not_accessible','bathroom_missing') and created_at>=now()-interval '7 days') into v_community_age,v_confirmations,v_conflicts from public.restroom_observations where location_id=p_location_id; v_community_score:=greatest(0,least(100,100-(v_community_age*3.333333)));if v_service.id is not null then v_service_score:=public.kleenest_service_freshness_score(v_service.event_kind,v_service.reported_at);end if; v_fresh:=greatest(v_community_score,v_service_score,coalesce(v_bi.freshness_score,0));if v_service.id is not null and v_service_score>=v_community_score and v_service_score>=coalesce(v_bi.freshness_score,0) then v_source:='business_reported';elsif v_confirmations>0 then v_source:='community';elsif coalesce(v_bi.evidence_count,0)>0 then v_source:='system';end if; v_label:=case when v_fresh>=85 then 'very_fresh' when v_fresh>=60 then 'fresh' when v_fresh>=30 then 'aging' else 'stale' end; v_availability:=case when v_service.id is not null and v_service.event_kind='closed' then 'business_reported_closed' when v_service.id is not null and v_service.event_kind='reopened' then 'business_reported_open' else coalesce(v_bi.access,'unknown') end; return jsonb_build_object('location_id',v_l.id,'name',v_l.name,'freshness_score',round(v_fresh,1),'freshness_label',v_label,'freshness_provenance',v_source,'freshness_at',greatest((case when v_community_age<9999 then now()-make_interval(secs=round(v_community_age*86400)::int) end),v_service.reported_at),'confidence_score',coalesce(v_lc.score,v_bi.confidence,0),'confidence_level',coalesce(v_lc.level,'unknown'),'independent_confirmations',v_confirmations,'recent_conflicts',v_conflicts,'bathroom_status',coalesce(v_bi.status,v_l.bathroom_verification_status,'unknown'),'availability',v_availability,'latest_service',case when v_service.id is null then null else jsonb_build_object('event_kind',v_service.event_kind,'reported_at',v_service.reported_at,'provenance','business_reported','freshness_score',v_service_score) end,'explanation',jsonb_build_object('freshness','Freshness can come from recent community evidence or a claimed business service update.','confidence','Confidence remains based on independent evidence and verification; business service reports do not become independent confirmations.'),'generated_at',now()); end $$;
create or replace function public.business_record_restroom_service_update(p_business_id uuid,p_location_id uuid,p_event_kind text,p_note text default null,p_proof_url text default null,p_restroom_facility_id uuid default null) returns jsonb language plpgsql security definer set search_path to '' as $$ declare v_location public.locations;v_id uuid;v_config jsonb;v_min_minutes int:=15;v_last timestamptz; begin if auth.uid() is null then raise exception 'Authentication required';end if;if not public.business_can_manage(p_business_id) then raise exception 'Business management access required';end if;if lower(coalesce(p_event_kind,'')) not in ('cleaned','restocked','inspected','repaired','deep_cleaned','renovated','closed','reopened') then raise exception 'Unsupported restroom service event';end if;select * into v_location from public.locations where id=p_location_id;if not found then raise exception 'Location not found';end if;if coalesce(v_location.claimed_business_id,v_location.business_id) is distinct from p_business_id and not exists(select 1 from public.location_claims c where c.location_id=p_location_id and c.business_id=p_business_id and c.status='approved') then raise exception 'This business does not manage the location';end if;select config into v_config from public.kleenest_intelligence_policy where policy_key='global_v1';v_min_minutes:=greatest(1,coalesce((v_config->>'service_min_interval_minutes')::int,15));select max(reported_at) into v_last from public.business_restroom_service_updates where business_id=p_business_id and location_id=p_location_id and event_kind=lower(p_event_kind);if v_last is not null and v_last>now()-make_interval(mins=>v_min_minutes) then raise exception 'A matching service update was recorded recently. Add new evidence after the cooldown.';end if;insert into public.business_restroom_service_updates(business_id,location_id,restroom_facility_id,event_kind,note,proof_url,actor_user_id,metadata) values(p_business_id,p_location_id,p_restroom_facility_id,lower(p_event_kind),nullif(trim(coalesce(p_note,'')),''),nullif(trim(coalesce(p_proof_url,'')),''),auth.uid(),jsonb_build_object('provenance','business_reported')) returning id into v_id;insert into public.data_feature_events(subject_type,subject_id,actor_user_id,business_id,location_id,event_type,feature_code,source_table,source_id,value_text,metadata,occurred_at,event_validity,confidence,deduplication_key) values('location',p_location_id,auth.uid(),p_business_id,p_location_id,'business_service_update','restroom_service_freshness','business_restroom_service_updates',v_id,lower(p_event_kind),jsonb_build_object('provenance','business_reported','service_event',lower(p_event_kind),'restroom_facility_id',p_restroom_facility_id),now(),'valid',.65,'business-service:'||v_id::text);perform public.compute_bathroom_intelligence(p_location_id);return jsonb_build_object('service_update_id',v_id,'now',public.location_kleenest_now(p_location_id));end $$;
create or replace function public.consumer_get_bathroom_fit_preferences() returns jsonb language sql stable security definer set search_path to '' as $$ select case when auth.uid() is null then '{}'::jsonb else coalesce((select preferences from public.consumer_bathroom_fit_preferences where user_id=auth.uid()),'{}'::jsonb) end $$;
create or replace function public.consumer_update_bathroom_fit_preferences(p_preferences jsonb) returns jsonb language plpgsql security definer set search_path to '' as $$ declare v_clean jsonb; begin if auth.uid() is null then raise exception 'Authentication required';end if;v_clean:=jsonb_build_object('accessible',coalesce((p_preferences->>'accessible')::boolean,false),'changing_table',coalesce((p_preferences->>'changing_table')::boolean,false),'family_restroom',coalesce((p_preferences->>'family_restroom')::boolean,false),'all_gender',coalesce((p_preferences->>'all_gender')::boolean,false),'single_occupancy',coalesce((p_preferences->>'single_occupancy')::boolean,false),'hands_free_door',coalesce((p_preferences->>'hands_free_door')::boolean,false),'toilet_seat_covers',coalesce((p_preferences->>'toilet_seat_covers')::boolean,false),'touchless_fixtures',coalesce((p_preferences->>'touchless_fixtures')::boolean,false),'quiet_private',coalesce((p_preferences->>'quiet_private')::boolean,false));insert into public.consumer_bathroom_fit_preferences(user_id,preferences,updated_at) values(auth.uid(),v_clean,now()) on conflict(user_id) do update set preferences=excluded.preferences,updated_at=now();return v_clean;end $$;
create or replace function public.location_bathroom_fit(p_location_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_prefs jsonb;v_requested text[]:='{}';v_matched text[]:='{}';v_missing text[]:='{}';v_key text;v_names text[];v_l public.locations;v_total int:=0;v_hits int:=0;begin if auth.uid() is null then return jsonb_build_object('score',null,'requested','[]'::jsonb,'matched','[]'::jsonb,'missing','[]'::jsonb,'reason','sign_in_for_fit');end if;v_prefs:=public.consumer_get_bathroom_fit_preferences();select * into v_l from public.locations where id=p_location_id;select coalesce(array_agg(lower(a.name)),'{}') into v_names from public.location_amenities la join public.amenities a on a.id=la.amenity_id where la.location_id=p_location_id;foreach v_key in array array['accessible','changing_table','family_restroom','all_gender','single_occupancy','hands_free_door','toilet_seat_covers','touchless_fixtures','quiet_private'] loop if coalesce((v_prefs->>v_key)::boolean,false) then v_total:=v_total+1;v_requested:=array_append(v_requested,v_key);if(v_key='accessible' and coalesce(v_l.accessible,false)) or(v_key='changing_table' and coalesce(v_l.changing_table,false)) or exists(select 1 from unnest(v_names)n where replace(replace(n,' ','_'),'-','_') like '%'||v_key||'%') then v_hits:=v_hits+1;v_matched:=array_append(v_matched,v_key);else v_missing:=array_append(v_missing,v_key);end if;end if;end loop;return jsonb_build_object('score',case when v_total=0 then null else round((100.0*v_hits/v_total)::numeric) end,'requested',to_jsonb(v_requested),'matched',to_jsonb(v_matched),'missing',to_jsonb(v_missing),'reason',case when v_total=0 then 'no_fit_preferences' else 'preference_match' end);end $$;
create or replace function public.consumer_journey_collections() returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_user uuid:=auth.uid();v_mo int:=0;v_il int:=0;v_corridor int:=0;v_places int:=0;begin if v_user is null then raise exception 'Authentication required';end if;select count(distinct lower(city_snapshot)) filter(where upper(coalesce(state_snapshot,'')) in('MO','MISSOURI')),count(distinct lower(city_snapshot)) filter(where upper(coalesce(state_snapshot,'')) in('IL','ILLINOIS')),count(distinct lower(city_snapshot)) filter(where lower(coalesce(city_snapshot,'')) in('st. louis','saint louis','springfield','normal','bloomington','chicago')),count(*) into v_mo,v_il,v_corridor,v_places from public.user_passport_visits where user_id=v_user;return jsonb_build_array(jsonb_build_object('code','missouri_explorer','name','Missouri Explorer','description','Verify trusted stops across five Missouri cities.','current',least(v_mo,5),'target',5),jsonb_build_object('code','illinois_explorer','name','Illinois Explorer','description','Verify trusted stops across five Illinois cities.','current',least(v_il,5),'target',5),jsonb_build_object('code','i55_trail','name','I-55 Trail','description','Build a verified trail through St. Louis, Springfield/Normal and Chicago corridor cities.','current',least(v_corridor,4),'target',4),jsonb_build_object('code','road_regular','name','Road Regular','description','Build a ten-place verified travel book.','current',least(v_places,10),'target',10));end $$;
create or replace function public.location_facility_passport(p_location_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_l public.locations;v_now jsonb;v_milestones jsonb;v_claimed boolean;v_review_count bigint;v_observation_count bigint;v_amenity_count bigint;v_service_count bigint;v_resolved_count bigint;begin select * into v_l from public.locations where id=p_location_id;if not found then raise exception 'Location not found';end if;v_now:=public.location_kleenest_now(p_location_id);select exists(select 1 from public.location_claims c where c.location_id=p_location_id and c.status='approved') or v_l.claimed_business_id is not null into v_claimed;select count(*) into v_review_count from public.reviews where location_id=p_location_id and coalesce(status::text,'published')<>'deleted';select count(*) into v_observation_count from public.restroom_observations where location_id=p_location_id;select count(*) into v_amenity_count from public.location_amenities where location_id=p_location_id;select count(*) into v_service_count from public.business_restroom_service_updates where location_id=p_location_id;select count(*) into v_resolved_count from public.business_restroom_remediation_cases where location_id=p_location_id and status in('resolved','closed','completed');select coalesce(jsonb_agg(to_jsonb(x) order by x.occurred_at desc),'[]'::jsonb) into v_milestones from(select 'discovered'::text kind,v_l.created_at occurred_at,'Added to the Kleenest location network'::text label,'system'::text provenance union all select 'verified',v_l.bathroom_verified_at,'Bathroom verification recorded','community' where v_l.bathroom_verified_at is not null union all select 'claimed',c.updated_at,'Claimed business connected','business_reported' from public.location_claims c where c.location_id=p_location_id and c.status='approved' order by c.updated_at desc limit 1)x;v_milestones:=v_milestones||coalesce((select jsonb_agg(jsonb_build_object('kind','service','occurred_at',s.reported_at,'label',replace(s.event_kind,'_',' '),'provenance','business_reported') order by s.reported_at desc) from(select * from public.business_restroom_service_updates where location_id=p_location_id order by reported_at desc limit 12)s),'[]'::jsonb);return jsonb_build_object('location',jsonb_build_object('id',v_l.id,'name',v_l.name,'address',v_l.address,'city',v_l.city,'state',v_l.state,'place_type',v_l.place_type,'claimed',v_claimed),'now',v_now,'summary',jsonb_build_object('reviews',v_review_count,'observations',v_observation_count,'amenities',v_amenity_count,'service_updates',v_service_count,'resolved_recovery_cases',v_resolved_count),'milestones',v_milestones,'generated_at',now());end $$;
create or replace function public.kleenest_verified_access(p_location_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_user uuid:=auth.uid();v_bi public.location_bathroom_intelligence;v_source text:='none';v_allowed boolean:=false;v_reason text:='No verified access entitlement is active for this location.';v_until timestamptz;v_program uuid;begin select * into v_bi from public.location_bathroom_intelligence where location_id=p_location_id;if coalesce(v_bi.access,'') in('public','permissive') then v_allowed:=true;v_source:='public_access';v_reason:='This location is currently represented as public/permissive access in Kleenest.';end if;if v_user is null then return jsonb_build_object('allowed',v_allowed,'source',v_source,'reason',v_reason,'expires_at',v_until);end if;if exists(select 1 from public.preferred_location_activations a where a.user_id=v_user and a.location_id=p_location_id and a.deactivated_at is null) then v_allowed:=true;v_source:='preferred_access';v_reason:='Your preferred-location activation includes this facility.';end if;if not v_allowed and exists(select 1 from public.single_use_access_purchases p join public.single_use_access_offers o on o.id=p.offer_id join public.partner_program_locations pl on pl.partner_program_id=o.partner_program_id where p.user_id=v_user and p.status='purchased' and p.redeemed_at is null and pl.location_id=p_location_id and pl.status='active' and o.enabled and(o.expires_at is null or o.expires_at>now())) then v_allowed:=true;v_source:='single_use';v_reason:='You have an unused single-use access pass for this partner location.';end if;select pl.partner_program_id into v_program from public.partner_program_locations pl join public.partner_programs pp on pp.id=pl.partner_program_id where pl.location_id=p_location_id and pl.status='active' and pp.enabled and pp.preferred_access order by pp.created_at desc limit 1;if not v_allowed and v_program is not null and exists(select 1 from public.can_activate_preferred_location(p_location_id)e where e.eligible) then v_allowed:=true;v_source:=case when exists(select 1 from public.fleet_premium_memberships m where m.user_id=v_user and m.status='active') then 'fleet_premium' when public.family_has_premium_access(v_user) then 'family_premium' else 'consumer_premium' end;v_reason:='Your scoped Kleenest Premium membership is eligible for this preferred-access partner.';end if;return jsonb_build_object('allowed',v_allowed,'source',v_source,'reason',v_reason,'partner_program_id',v_program,'expires_at',v_until,'checked_at',now());end $$;
create or replace function public.business_trust_recovery(p_business_id uuid,p_limit integer default 40) returns jsonb language plpgsql stable security definer set search_path to '' as $$ begin if auth.uid() is null then raise exception 'Authentication required';end if;if not public.business_can_manage(p_business_id) and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role::text='analyst') then raise exception 'Business access required';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by x.occurred_at desc) from(select l.id location_id,l.name,'service'::text event_type,s.event_kind::text status,s.reported_at occurred_at,'business_reported'::text provenance,public.location_kleenest_now(l.id) current_state from public.business_restroom_service_updates s join public.locations l on l.id=s.location_id where s.business_id=p_business_id union all select l.id,l.name,'remediation',r.status::text,coalesce(r.resolved_at,r.started_at,r.opened_at),case when r.status in('resolved','closed','completed') then 'business_reported' else 'system' end,public.location_kleenest_now(l.id) from public.business_restroom_remediation_cases r join public.locations l on l.id=r.location_id where r.business_id=p_business_id order by occurred_at desc limit least(greatest(p_limit,1),100))x),'[]'::jsonb);end $$;
create or replace function public.business_fix_first_queue(p_business_id uuid,p_limit integer default 20) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_policy jsonb;begin if auth.uid() is null then raise exception 'Authentication required';end if;if not public.business_can_manage(p_business_id) and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role::text='analyst') then raise exception 'Business access required';end if;select config into v_policy from public.kleenest_intelligence_policy where policy_key='global_v1';return coalesce((select jsonb_agg(to_jsonb(q) order by q.priority_score desc,q.name) from(select l.id location_id,l.name,l.city,l.state,round(((100-coalesce((z.n->>'freshness_score')::numeric,0))*coalesce((v_policy->'fix_first'->>'freshness_weight')::numeric,.45)+greatest(0,75-coalesce(l.cleanliness_pct,50))*coalesce((v_policy->'fix_first'->>'cleanliness_weight')::numeric,.25)+(select count(*) from public.business_restroom_remediation_cases r where r.location_id=l.id and r.status not in('resolved','closed','completed'))*coalesce((v_policy->'fix_first'->>'active_case_weight')::numeric,20)+(select count(*) from public.restroom_observations ro where ro.location_id=l.id and ro.created_at>=now()-interval '7 days' and ro.observation_type in('dirty','supplies_low','closed','not_accessible'))*coalesce((v_policy->'fix_first'->>'negative_observation_weight')::numeric,5))::numeric,1) priority_score,array_remove(array[case when coalesce((z.n->>'freshness_score')::numeric,0)<40 then 'stale freshness evidence' end,case when coalesce(l.cleanliness_pct,50)<70 then 'cleanliness below target' end,case when exists(select 1 from public.business_restroom_remediation_cases r where r.location_id=l.id and r.status not in('resolved','closed','completed')) then 'active remediation' end,case when exists(select 1 from public.restroom_observations ro where ro.location_id=l.id and ro.created_at>=now()-interval '7 days' and ro.observation_type in('dirty','supplies_low','closed','not_accessible')) then 'recent negative evidence' end],null) reasons,z.n current_state from public.locations l cross join lateral(select public.location_kleenest_now(l.id)n)z where coalesce(l.claimed_business_id,l.business_id)=p_business_id order by priority_score desc limit least(greatest(p_limit,1),50))q),'[]'::jsonb);end $$;
create or replace function public.business_local_freshness_benchmark(p_business_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ begin if auth.uid() is null then raise exception 'Authentication required';end if;if not public.business_can_manage(p_business_id) and not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role::text='analyst') then raise exception 'Business access required';end if;return coalesce((select jsonb_agg(to_jsonb(x) order by x.name) from(select l.id location_id,l.name,l.city,l.state,round(coalesce(bi.freshness_score,0),1) freshness_score,round(coalesce((select avg(b2.freshness_score) from public.locations p join public.location_bathroom_intelligence b2 on b2.location_id=p.id where lower(coalesce(p.city,''))=lower(coalesce(l.city,'')) and upper(coalesce(p.state,''))=upper(coalesce(l.state,'')) and p.id<>l.id),coalesce(bi.freshness_score,0)),1)local_freshness_average,round(coalesce(bi.freshness_score,0)-coalesce((select avg(b2.freshness_score) from public.locations p join public.location_bathroom_intelligence b2 on b2.location_id=p.id where lower(coalesce(p.city,''))=lower(coalesce(l.city,'')) and upper(coalesce(p.state,''))=upper(coalesce(l.state,'')) and p.id<>l.id),coalesce(bi.freshness_score,0)),1)freshness_delta from public.locations l left join public.location_bathroom_intelligence bi on bi.location_id=l.id where coalesce(l.claimed_business_id,l.business_id)=p_business_id)x),'[]'::jsonb);end $$;
create or replace function public.fleet_route_relief_coverage(p_business_id uuid,p_route_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_route public.fleet_routes;v_total int:=0;v_covered int:=0;v_preferred int:=0;v_longest int:=0;v_est numeric:=0;v_threshold numeric:=45;v_conf_threshold numeric:=40;v_desert int:=45;v_policy jsonb;v_stops jsonb;begin if auth.uid() is null or not public.fleet_observe_access(p_business_id) then raise exception 'Fleet access required';end if;select * into v_route from public.fleet_routes where id=p_route_id and business_id=p_business_id;if not found then raise exception 'Route not found';end if;select config into v_policy from public.kleenest_intelligence_policy where policy_key='global_v1';v_threshold:=coalesce((v_policy->'fleet'->>'trusted_freshness_min')::numeric,45);v_conf_threshold:=coalesce((v_policy->'fleet'->>'trusted_confidence_min')::numeric,40);v_desert:=coalesce((v_policy->'fleet'->>'restroom_desert_minutes')::int,45);with base as(select s.id,s.stop_order,s.location_id,coalesce(s.stop_name,l.name)name,s.planned_arrival_at,case when s.location_id is null then null else public.location_kleenest_now(s.location_id)end n,case when s.location_id is null then null else public.kleenest_verified_access(s.location_id)end a from public.fleet_route_stops s left join public.locations l on l.id=s.location_id where s.route_id=p_route_id and s.business_id=p_business_id),tagged as(select *,coalesce((n->>'freshness_score')::numeric,0)>=v_threshold and coalesce((n->>'confidence_score')::numeric,0)>=v_conf_threshold and coalesce(n->>'bathroom_status','unknown')<>'no_bathroom' covered from base)select count(*),count(*)filter(where covered),count(*)filter(where coalesce((a->>'allowed')::boolean,false) and a->>'source' in('preferred_access','fleet_premium','family_premium','consumer_premium')),coalesce(jsonb_agg(jsonb_build_object('stop_id',id,'stop_order',stop_order,'location_id',location_id,'name',name,'covered',covered,'kleenest_now',n,'verified_access',a)order by stop_order),'[]'::jsonb)into v_total,v_covered,v_preferred,v_stops from tagged;with t as(select s.stop_order,(coalesce((public.location_kleenest_now(s.location_id)->>'freshness_score')::numeric,0)>=v_threshold and coalesce((public.location_kleenest_now(s.location_id)->>'confidence_score')::numeric,0)>=v_conf_threshold)covered from public.fleet_route_stops s where s.route_id=p_route_id and s.business_id=p_business_id and s.location_id is not null),g as(select *,sum(case when covered then 1 else 0 end)over(order by stop_order)grp from t),runs as(select count(*)n from g where not covered group by grp)select coalesce(max(n),0)into v_longest from runs;v_est:=case when v_total=0 then 0 else coalesce(v_route.estimated_minutes,0)::numeric/v_total end;return jsonb_build_object('route_id',p_route_id,'route_name',v_route.name,'coverage_pct',case when v_total=0 then 0 else round(100.0*v_covered/v_total,1)end,'trusted_stop_count',v_covered,'total_stops',v_total,'preferred_access_count',v_preferred,'longest_uncovered_stops',v_longest,'longest_uncovered_minutes_estimate',round(v_longest*v_est,1),'restroom_desert',v_longest*v_est>=v_desert,'restroom_desert_threshold_minutes',v_desert,'basis',case when v_route.estimated_minutes is null then 'stop_sequence' else 'route_estimate' end,'stops',v_stops,'generated_at',now());end $$;
create or replace function public.owner_get_intelligence_policy() returns jsonb language plpgsql stable security definer set search_path to '' as $$ begin if not public.is_platform_owner_session()then raise exception 'Platform owner access required';end if;return coalesce((select config from public.kleenest_intelligence_policy where policy_key='global_v1'),'{}'::jsonb);end $$;
create or replace function public.owner_update_intelligence_policy(p_patch jsonb) returns jsonb language plpgsql security definer set search_path to '' as $$ declare v_config jsonb;begin if not public.is_platform_owner_session()then raise exception 'Platform owner access required';end if;update public.kleenest_intelligence_policy set config=config||coalesce(p_patch,'{}'::jsonb),updated_at=now(),updated_by=auth.uid()where policy_key='global_v1' returning config into v_config;return v_config;end $$;
create or replace function public.owner_intelligence_overview() returns jsonb language plpgsql stable security definer set search_path to '' as $$ declare v_policy jsonb;v_fresh numeric:=50;v_conf numeric:=40;v_graph jsonb;v_markets jsonb;begin if not public.is_platform_owner_session()then raise exception 'Platform owner access required';end if;select config into v_policy from public.kleenest_intelligence_policy where policy_key='global_v1';v_fresh:=coalesce((v_policy->'launch'->>'freshness_min')::numeric,50);v_conf:=coalesce((v_policy->'launch'->>'confidence_min')::numeric,40);v_graph:=jsonb_build_object('users',(select count(*)from public.profiles),'locations',(select count(*)from public.locations),'businesses',(select count(*)from public.businesses),'fleet_routes',(select count(*)from public.fleet_routes),'service_updates',(select count(*)from public.business_restroom_service_updates),'evidence_events',(select count(*)from public.kleenest_evidence_events),'preferred_access_activations',(select count(*)from public.preferred_location_activations where deactivated_at is null),'reviews',(select count(*)from public.reviews),'visits',(select count(*)from public.location_visits));select coalesce(jsonb_agg(to_jsonb(x)order by x.locations desc),'[]'::jsonb)into v_markets from(select coalesce(l.city,'Unknown')city,coalesce(l.state,'')state,count(*)locations,count(*)filter(where coalesce(bi.freshness_score,0)>=v_fresh)fresh_locations,round(100.0*count(*)filter(where coalesce(bi.freshness_score,0)>=v_fresh)/greatest(count(*),1),1)fresh_pct,count(*)filter(where coalesce(l.claimed_business_id,l.business_id)is not null)claimed_locations,round(100.0*count(*)filter(where coalesce(l.claimed_business_id,l.business_id)is not null)/greatest(count(*),1),1)claimed_pct,count(*)filter(where coalesce(lc.score,0)>=v_conf)confident_locations,(select count(*)from public.business_restroom_service_updates s join public.locations sl on sl.id=s.location_id where lower(coalesce(sl.city,''))=lower(coalesce(l.city,'')) and upper(coalesce(sl.state,''))=upper(coalesce(l.state,'')) and s.reported_at>=now()-interval '30 days')service_updates_30d from public.locations l left join public.location_bathroom_intelligence bi on bi.location_id=l.id left join public.location_confidence lc on lc.location_id=l.id group by l.city,l.state order by locations desc limit 50)x;return jsonb_build_object('platform_graph',v_graph,'launch_readiness',v_markets,'thresholds',v_policy->'launch','generated_at',now());end $$;
create or replace function public.owner_explain_location_intelligence(p_location_id uuid) returns jsonb language plpgsql stable security definer set search_path to '' as $$ begin if not public.is_platform_owner_session()then raise exception 'Platform owner access required';end if;return jsonb_build_object('now',public.location_kleenest_now(p_location_id),'facility_passport',public.location_facility_passport(p_location_id),'evidence',coalesce((select jsonb_agg(jsonb_build_object('kind',e.evidence_kind,'provenance',e.provenance,'observed_at',e.observed_at,'confidence',e.confidence,'source_type',e.source_type,'payload',e.payload)order by e.observed_at desc)from(select * from public.kleenest_evidence_events where location_id=p_location_id order by observed_at desc limit 50)e),'[]'::jsonb),'policy',(select config from public.kleenest_intelligence_policy where policy_key='global_v1'),'generated_at',now());end $$;
revoke all on function public.business_record_restroom_service_update(uuid,uuid,text,text,text,uuid) from public;grant execute on function public.business_record_restroom_service_update(uuid,uuid,text,text,text,uuid) to authenticated;grant execute on function public.location_kleenest_now(uuid)to anon,authenticated;grant execute on function public.location_facility_passport(uuid)to anon,authenticated;grant execute on function public.kleenest_verified_access(uuid)to anon,authenticated;grant execute on function public.location_bathroom_fit(uuid)to authenticated;grant execute on function public.consumer_get_bathroom_fit_preferences()to authenticated;grant execute on function public.consumer_update_bathroom_fit_preferences(jsonb)to authenticated;grant execute on function public.consumer_journey_collections()to authenticated;grant execute on function public.business_trust_recovery(uuid,integer)to authenticated;grant execute on function public.business_fix_first_queue(uuid,integer)to authenticated;grant execute on function public.business_local_freshness_benchmark(uuid)to authenticated;grant execute on function public.fleet_route_relief_coverage(uuid,uuid)to authenticated;grant execute on function public.owner_get_intelligence_policy()to authenticated;grant execute on function public.owner_update_intelligence_policy(jsonb)to authenticated;grant execute on function public.owner_intelligence_overview()to authenticated;grant execute on function public.owner_explain_location_intelligence(uuid)to authenticated;
